    vector<char> isFriend(n, 0);
    string out;
    for (int i = 0; i < n; i++) {
        for (int f : fr[i]) isFriend[f] = 1;
        // count two-hop paths i -> middle -> candidate (one per mutual friend)
        vector<int> touched;
        for (int mid : fr[i])
            for (int c : fr[mid])
                if (c != i && !isFriend[c]) { if (cnt[c]++ == 0) touched.push_back(c); }
