import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), m = (int) nextLong();
        int[] ea = new int[m], eb = new int[m], deg = new int[n];
        for (int i = 0; i < m; i++) {
            ea[i] = (int) nextLong() - 1;
            eb[i] = (int) nextLong() - 1;
            deg[ea[i]]++;
            deg[eb[i]]++;
        }
        int[][] fr = new int[n][];
        for (int i = 0; i < n; i++) fr[i] = new int[deg[i]];
        int[] fill = new int[n];
        for (int i = 0; i < m; i++) {
            fr[ea[i]][fill[ea[i]]++] = eb[i];
            fr[eb[i]][fill[eb[i]]++] = ea[i];
        }
        int[] cnt = new int[n];
        boolean[] isFriend = new boolean[n];
        int[] touched = new int[256];
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int f : fr[i]) isFriend[f] = true;
            // count two-hop paths i -> middle -> candidate (one per mutual friend)
            int t = 0;
            for (int mid : fr[i])
                for (int c : fr[mid])
                    if (c != i && !isFriend[c]) { if (cnt[c]++ == 0) touched[t++] = c; }
            int best = -1;
            for (int k = 0; k < t; k++) {
                int c = touched[k];
                if (best < 0 || cnt[c] > cnt[best] || (cnt[c] == cnt[best] && c < best)) best = c;
            }
            if (best < 0) {
                // no positive count: smallest id that is neither i nor a friend
                best = 0;
                while (best < n && (best == i || isFriend[best])) best++;
                if (best == n) best = -1;
            }
            for (int k = 0; k < t; k++) cnt[touched[k]] = 0;
            for (int f : fr[i]) isFriend[f] = false;
            if (i > 0) out.append(' ');
            out.append(best < 0 ? -1 : best + 1);
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, m := nextInt(), nextInt()
	fr := make([][]int, n)
	for i := 0; i < m; i++ {
		a, b := nextInt()-1, nextInt()-1
		fr[a] = append(fr[a], b)
		fr[b] = append(fr[b], a)
	}
	cnt := make([]int, n)
	isFriend := make([]bool, n)
	touched := make([]int, 0, 256)
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	for i := 0; i < n; i++ {
		for _, f := range fr[i] {
			isFriend[f] = true
		}
		// count two-hop paths i -> middle -> candidate (one per mutual friend)
		touched = touched[:0]
		for _, mid := range fr[i] {
			for _, c := range fr[mid] {
				if c != i && !isFriend[c] {
					if cnt[c] == 0 {
						touched = append(touched, c)
					}
					cnt[c]++
				}
			}
		}
		best := -1
		for _, c := range touched {
			if best < 0 || cnt[c] > cnt[best] || (cnt[c] == cnt[best] && c < best) {
				best = c
			}
		}
		if best < 0 {
			// no positive count: smallest id that is neither i nor a friend
			best = 0
			for best < n && (best == i || isFriend[best]) {
				best++
			}
			if best == n {
				best = -1
			}
		}
		for _, c := range touched {
			cnt[c] = 0
		}
		for _, f := range fr[i] {
			isFriend[f] = false
		}
		if i > 0 {
			w.WriteByte(' ')
		}
		if best < 0 {
			w.WriteString("-1")
		} else {
			w.WriteString(strconv.Itoa(best + 1))
		}
	}
	w.WriteByte('\n')
}
